57	export async function GET(
58	  req: NextRequest,
59	  { params }: { params: Promise<{ serverId: string }> }
60	) {
61	  const { serverId } = await params;
62	
63	  const user = await currentUser();
64	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
65	
66	  const rl = checkRateLimit(`files:download:${user.id}`, { max: 60, windowMs: 60_000 });
67	  if (!rl.ok) {
68	    return NextResponse.json(
69	      { error: "too many downloads — slow down", retryAfterSec: rl.retryAfterSec },
70	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
71	    );
72	  }
73	
74	  const server = await ownedServer(serverId, user.id, user.role === "ADMIN");
75	  if (!server) return NextResponse.json({ error: "not found" }, { status: 404 });
76	
77	  let path: string;
78	  try {
79	    path = normalizePath(req.nextUrl.searchParams.get("path") ?? "");
80	  } catch (err) {
81	    return NextResponse.json(
82	      { error: err instanceof Error ? err.message : "invalid path" },
83	      { status: 400 }
84	    );
85	  }
86	  if (path === "/") return NextResponse.json({ error: "not a file" }, { status: 400 });
87	
88	  let data: Buffer;
89	  try {
90	    data = await readFileBuffer(server, path);
91	  } catch (err) {
92	    const msg = err instanceof Error ? err.message : "read failed";
93	    const status = /No such|Not a file/i.test(msg) ? 404 : 502;
94	    return NextResponse.json({ error: msg }, { status });
95	  }
96	
97	  const filename = path.split("/").pop() || "download";
98	  // Always force a download to avoid the browser rendering server content inline.
99	  return new NextResponse(data as unknown as BodyInit, {
100	    status: 200,
101	    headers: {
102	      "Content-Type": "application/octet-stream",
103	      "Content-Length": String(data.length),
104	      "Content-Disposition": `attachment; filename="${filename.replace(/["\\]/g, "_")}"`,
105	      "Cache-Control": "private, no-store",
106	    },
107	  });
108	}
