110	export async function POST(
111	  req: NextRequest,
112	  { params }: { params: Promise<{ serverId: string }> }
113	) {
114	  const { serverId } = await params;
115	
116	  const user = await currentUser();
117	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
118	
119	  const rl = checkRateLimit(`files:upload:${user.id}`, { max: 30, windowMs: 60_000 });
120	  if (!rl.ok) {
121	    return NextResponse.json(
122	      { error: "too many uploads — slow down", retryAfterSec: rl.retryAfterSec },
123	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
124	    );
125	  }
126	
127	  const server = await ownedServer(serverId, user.id, user.role === "ADMIN");
128	  if (!server) return NextResponse.json({ error: "not found" }, { status: 404 });
129	
130	  let dir: string;
131	  try {
132	    dir = normalizePath(req.nextUrl.searchParams.get("path") ?? "");
133	  } catch (err) {
134	    return NextResponse.json(
135	      { error: err instanceof Error ? err.message : "invalid path" },
136	      { status: 400 }
137	    );
138	  }
139	
140	  let form: FormData;
141	  try {
142	    form = await req.formData();
143	  } catch {
144	    return NextResponse.json({ error: "expected a multipart upload" }, { status: 400 });
145	  }
146	
147	  const file = form.get("file");
148	  if (!(file instanceof File)) {
149	    return NextResponse.json({ error: "no file provided" }, { status: 400 });
150	  }
151	  if (file.size > MAX_UPLOAD_BYTES) {
152	    return NextResponse.json(
153	      { error: `file exceeds the ${MAX_UPLOAD_BYTES / (1024 * 1024)} MB upload limit` },
154	      { status: 413 }
155	    );
156	  }
157	
158	  let target: string;
159	  try {
160	    const name = validateName((file.name || "upload").trim());
161	    target = joinPath(dir, name);
162	  } catch (err) {
163	    return NextResponse.json(
164	      { error: err instanceof Error ? err.message : "invalid filename" },
165	      { status: 400 }
166	    );
167	  }
168	
169	  try {
170	    const data = Buffer.from(await file.arrayBuffer());
171	    // Re-check the actual byte length in case the reported size was understated.
172	    if (data.length > MAX_UPLOAD_BYTES) {
173	      return NextResponse.json({ error: "file too large" }, { status: 413 });
174	    }
175	    // Best-effort: create the destination directory. The file manager always
176	    // targets an existing dir (mkdir throws "already exists" → ignored), but the
177	    // Matrix console uploads into ~/nxeon-uploads, which may not exist yet, and
178	    // client.put() does not create parent dirs. Harmless when it already exists.
179	    try {
180	      await mkdirPath(server, dir);
181	    } catch {
182	      /* already exists / benign — the write below surfaces any real failure */
183	    }
184	    await writeFileBuffer(server, target, data);
185	  } catch (err) {
186	    const msg = err instanceof Error ? err.message : "upload failed";
187	    const status = /Invalid|directory/i.test(msg) ? 400 : 502;
188	    return NextResponse.json({ error: msg }, { status });
189	  }
190	
191	  return NextResponse.json({ ok: true, path: target });
192	}
